<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { api } from '../../api/client';
import type { paths } from '../../api/generated/admin';
import { credits,consumerDate } from './consumer-format';
const emit=defineEmits<{changed:[]}>();
const data=ref<paths['/user/api/entitlements']['get']['responses'][200]['content']['application/json']>();const code=ref(''),busy=ref(false),error=ref(''),message=ref('');
async function load(){data.value=await api('/user/api/entitlements');}
async function redeem(){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await api('/user/api/redeem',{method:'POST',body:{code:code.value}});code.value='';await load();emit('changed');message.value='兑换成功';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(()=>load().catch(e=>error.value=(e as Error).message));
</script>
<template><section class="card consumer-form" id="userEntitlements"><h2>我的额度与订阅</h2><template v-if="data"><div class="user-summary"><div><span class="hint">参考 USD 额度</span><strong>{{data.wallet.enabled?credits(data.wallet.balance):'不限余额'}}</strong></div><div><span class="hint">在途预留</span><strong>{{credits(data.reserved)}}</strong></div><div><span class="hint">当前套餐</span><strong>{{data.subscription.id?data.subscription.plan.name:'无订阅'}}</strong></div></div><p v-if="data.wallet.review_required" class="err-text">部分请求缺少用量或价格，额度调用已暂停，请联系管理员核对。</p><p v-if="data.subscription.id">有效期至 {{consumerDate(data.subscription.expires_at)}} · {{data.subscription.disabled?'已停用':data.subscription.expires_at<Date.now()/1000?'已到期':'生效中'}} · 套餐并发 {{data.subscription.plan.max_concurrency||'不限'}} · 本周期已用 {{data.subscription.usage.requests}} 次 / {{data.subscription.plan.budget.max_requests||'不限'}}，{{data.subscription.usage.tokens}} Token，${{data.subscription.usage.usd.toFixed(6)}}</p></template>
<form class="actions" @submit.prevent="redeem"><input v-model="code" aria-label="兑换码" placeholder="输入额度、并发或套餐兑换码" required maxlength="200" autocomplete="off"><button class="btn primary" :disabled="busy">兑换</button></form><p v-if="message" role="status">{{message}}</p><p v-if="error" class="err-text" role="alert">{{error}}</p><h3>兑换记录</h3><div class="table-wrap"><table><thead><tr><th>时间</th><th>兑换码</th><th>权益</th></tr></thead><tbody><tr v-for="r in data?.redemptions.slice().reverse()??[]" :key="r.id"><td>{{consumerDate(r.used_at)}}</td><td>{{r.hint}}</td><td>{{r.kind==='balance'?credits(r.amount)+' USD':r.kind==='concurrency'?'并发 +'+r.concurrency:'套餐订阅'}}</td></tr><tr v-if="!data?.redemptions.length"><td colspan="3" class="empty">暂无兑换记录</td></tr></tbody></table></div><h3>额度流水</h3><div class="table-wrap"><table><thead><tr><th>时间</th><th>类型</th><th>变动 USD</th><th>结余 USD</th><th>说明</th></tr></thead><tbody><tr v-for="e in data?.entries??[]" :key="e.id"><td>{{consumerDate(e.time)}}</td><td>{{e.kind==='admin'?'管理员调整':e.kind==='redeem'?'兑换':'调用消耗'}}</td><td>{{credits(e.delta)}}</td><td>{{credits(e.balance)}}</td><td>{{e.note}}</td></tr><tr v-if="!data?.entries.length"><td colspan="5" class="empty">暂无流水</td></tr></tbody></table></div><p class="hint">额度与上游积分独立，按已配置参考价格结算。流水保留在全站最近 {{data?.retention_limit??10000}} 条范围内，累计余额独立保留。</p></section></template>
